const icon=name=>window.UIIcons?.[name]||`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.heart}"/></svg>`;
function hydrateIcons(){document.querySelectorAll('[data-icon]').forEach(el=>el.outerHTML=icon(el.dataset.icon))}
const cards=[{id:'venue',category:'VENUE',categoryKo:'웨딩홀',title:'햇살이 머무는, 자연스러운 웨딩',meta:'밝은 홀 · 내추럴 · 하우스 웨딩',image:'assets/venue.jpg',description:'큰 창으로 들어오는 빛, 초록이 보이는 풍경. 두 사람의 취향에 맞는 웨딩 공간을 찾아보세요.',tips:['자연광이 들어오는 시간 확인하기','보증 인원과 식사 구성 비교하기','대관 시간과 동선 살펴보기']},{id:'studio',category:'STUDIO & DRESS',categoryKo:'스튜디오',title:'시간이 지나도, 우리다운 한 장',meta:'흑백 스냅 · 인물 중심 · 미니멀',image:'assets/couple.jpg',description:'거창한 포즈보다 자연스러운 순간. 오래 꺼내 보고 싶은 두 사람의 모습을 기록하는 촬영 무드입니다.',tips:['좋아하는 사진의 무드 모아보기','촬영 의상과 배경 색상 맞춰보기','원본과 보정본 제공 범위 확인하기']},{id:'flower',category:'WEDDING DETAILS',categoryKo:'플라워',title:'작은 디테일이 만드는 분위기',meta:'화이트 부케 · 계절의 꽃 · 심플',image:'assets/bouquet.jpg',description:'담백한 화이트 부케와 계절의 꽃. 드레스와 공간에 어울리는 작은 디테일로 우리만의 분위기를 완성해보세요.',tips:['예식 계절에 구할 수 있는 꽃 확인하기','드레스 실루엣과 부케 크기 맞추기','좋아하는 꽃과 피하고 싶은 향 기록하기']}];
let saved=new Set(['flower']),filter='전체',curationFilter='전체',page='home';
const app=document.querySelector('#app');
const names={roadmap:'결혼 준비 로드맵',essentials:'준비물 체크리스트',family:'상견례 장소',invitation:'청첩장 모임',snap:'셀프 웨딩 스냅',color:'웨딩 컬러 · 골격 진단',collections:'테마 컬렉션',excel:'웨딩홀 비교 · 엑셀',methodology:'정보 확인 가이드',home:'준비 현황',checklist:'나의 할 일',budget:'예산',halls:'웨딩홀 찾기',survey:'내 기준 서베이',curation:'웨딩 추천',scrap:'저장한 추천'};
const pageNums={home:'01',checklist:'01',budget:'01',roadmap:'01',essentials:'01',halls:'02',survey:'02',collections:'02',excel:'02',family:'03',invitation:'03',curation:'04',snap:'04',color:'04',scrap:'05',methodology:'05'};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function heading(english,korean,desc,action=''){return `<div class="page-heading"><div><span class="section-eyebrow">CHAPTER ${pageNums[page]}</span><h1>${korean}</h1><p class="page-description">${desc}</p></div>${action?`<div class="page-action">${action}</div>`:''}</div>`}
function sectionHead(no,title,href,label='전체 보기'){return `<div class="section-head"><h2><span class="section-index">${no}</span>${title}</h2>${href?`<a class="text-button" href="#${href}">${label} ${icon('arrow')}</a>`:''}</div>`}
function cardGrid(list=cards){return `<div class="curation-grid">${list.map(c=>`<article class="curation-card reveal"><div class="card-copy"><p class="card-category">${c.categoryKo==='스튜디오'?'촬영 · 드레스':c.categoryKo}</p><button class="card-title" data-detail="${c.id}">${c.title}</button><p class="card-meta">${c.meta}</p></div><div class="card-image"><button data-detail="${c.id}" aria-label="${c.title} 준비 가이드 보기"><img src="${c.image}" alt="${c.id==='venue'?'큰 창과 꽃 장식이 있는 모던한 웨딩 공간':c.id==='studio'?'손을 맞잡은 신랑 신부의 흑백 웨딩 사진':'흰 꽃으로 구성된 자연스러운 웨딩 부케'}" loading="lazy"></button></div><div class="card-actions">${c.id==='venue'?`<a class="text-button" href="#halls">웨딩홀 찾기 ${icon('arrow')}</a>`:`<button class="text-button" data-detail="${c.id}">준비 가이드 ${icon('arrow')}</button>`}<button class="save-button ${saved.has(c.id)?'saved':''}" data-save="${c.id}" aria-label="${c.title} ${saved.has(c.id)?'저장 취소':'저장'}" aria-pressed="${saved.has(c.id)}">${icon('bookmark')}<span>${saved.has(c.id)?'저장됨':'저장'}</span></button></div></article>`).join('')}</div>`}
function budgetCard(){return WeddingBudget.homeCard()}
function home(){return `<section class="journal-cover"><div class="cover-copy"><div class="chapter-title"><span class="section-eyebrow">OUR WEDDING JOURNAL</span></div><h1>Every moment,<br><em>ours.</em></h1><p class="cover-description">지우와 하준의 결혼 준비.<br>할 일을 확인하고, 예산과 취향을 함께 모아요.</p><div class="cover-date">${Planner.homeDate()}</div><a class="text-button cover-link" href="#checklist">할 일 확인하기 ${icon('arrow')}</a><p class="cover-bottom">A COLLECTION OF OUR DAYS.</p></div><div class="cover-gallery"><div class="mood-grid">${[{src:'couple',title:'우리의 순간',id:'studio'},{src:'dress',title:'드레스의 결',id:'studio'},{src:'rings',title:'서로의 약속',id:'flower'},{src:'venue',title:'함께할 공간',id:'venue'},{src:'flower',title:'계절의 꽃',id:'flower'},{src:'bouquet',title:'작은 디테일',id:'flower'}].map((m,i)=>`<a class="mood-tile mood-${m.src}" href="#${m.id==='venue'?'halls':'curation'}" aria-label="${m.title} ${m.id==='venue'?'웨딩홀 찾기':'웨딩 추천 보기'}" style="--tile-index:${i}"><img src="assets/${m.src}.jpg" alt="${m.title}" ${i>2?'loading="lazy"':''}><span>${m.title}</span></a>`).join('')}</div><div class="gallery-caption"><span>우리의 웨딩 무드</span><a class="gallery-link" href="#curation">추천 둘러보기 ${icon('arrow')}</a></div></div></section><div class="j-home-links">${[['roadmap','roadmap','준비 로드맵'],['halls','hall','웨딩홀 찾기'],['survey','survey','내 기준 세우기'],['excel','excel','웨딩홀 엑셀'],['family','dining','상견례 장소'],['invitation','dining','청첩장 모임'],['snap','camera','셀프 스냅'],['color','color','컬러 · 골격 진단']].map(([r,i,l])=>`<a href="#${r}">${icon(i)}${l}</a>`).join('')}</div><section class="journal-section progress-section reveal"><div class="section-label"><span class="section-eyebrow">AT A GLANCE</span><h2>준비 현황</h2><p>할 일과 예산을<br>한눈에 확인하세요.</p></div><div class="metrics"><a href="#checklist" class="metric">${Planner.homeStats()}</a><a href="#budget" class="metric">${WeddingBudget.homeMetric()}</a><a href="#scrap" class="metric"><span class="metric-label">저장한 추천</span><span class="metric-value">${saved.size}<small>개</small></span><span class="metric-note">저장 목록 보기</span></a></div></section><section class="journal-section reveal"><div class="section-label"><span class="section-eyebrow">THE NEXT CHAPTER</span><h2>다가오는 준비</h2><p>다가오는 준비를<br>함께 확인해요.</p></div><div class="two-column"><section>${sectionHead('','다가오는 할 일','checklist','할 일 전체 보기')}<div class="task-list">${Planner.upcoming()}</div></section><section>${sectionHead('','결혼 예산','budget','예산 상세 보기')}${budgetCard()}</section></div></section><section class="journal-section"><div class="section-label reveal"><span class="section-eyebrow">CURATED FOR YOU</span><h2>웨딩 추천</h2><p>분위기를 살펴보고<br>마음에 드는 추천을 저장하세요.</p><a href="#curation" class="text-button">전체 보기 ${icon('arrow')}</a></div><div>${cardGrid()}</div></section>`}
function budget(){return WeddingBudget.render()}
function curation(){return `${heading('','웨딩 추천','웨딩홀·촬영·꽃 장식을 살펴보고, 마음에 드는 추천은 저장하세요.')}<section class="hall-entry"><div><span class="section-eyebrow">WEDDING VENUE ARCHIVE</span><h2>우리에게 맞는 웨딩홀을 찾아보세요.</h2><p>실제 웨딩홀의 지역·식대·인원을 확인하고, 후보를 나란히 비교할 수 있어요.</p></div><a class="outline-button" href="#halls">웨딩홀 찾기 ${icon('arrow')}</a></section><section class="editorial-layout"><aside class="page-aside"><span class="section-eyebrow">카테고리</span><div class="filter-bar vertical-filters">${['전체','웨딩홀','스튜디오','플라워'].map(f=>`<button class="filter-button ${curationFilter===f?'active':''}" data-category="${f}" aria-pressed="${curationFilter===f}">${f}<span>${f==='전체'?cards.length:cards.filter(c=>c.categoryKo===f).length}</span></button>`).join('')}</div><p>‘준비 가이드’에서 확인할 내용을 읽고,<br>‘저장’을 누르면 저장 목록에 모여요.</p><a class="text-button" href="#scrap">저장한 추천 보기 ${icon('arrow')}</a></aside><div class="full-curation">${cardGrid(cards.filter(c=>curationFilter==='전체'||c.categoryKo===curationFilter))}<p class="note-label">분위기를 살펴보는 샘플 큐레이션입니다. 웨딩홀 실제 목록은 위의 ‘웨딩홀 찾기’에서 볼 수 있어요.</p></div></section>`}
function scrap(){let list=cards.filter(c=>saved.has(c.id));return `${heading('','저장한 추천',`웨딩 추천에서 저장한 ${list.length}개를 모았어요. ‘저장됨’을 다시 누르면 목록에서 빠집니다.`)}${VenueExplorer.savedSection()}<section class="editorial-layout"><aside class="page-aside"><span class="section-eyebrow">저장 목록</span><p>마음에 들었던 추천을<br>다시 살펴보세요.</p><span class="archive-count">${list.length}<small>개 저장됨</small></span><a href="#curation" class="text-button">웨딩 추천 더 보기 ${icon('arrow')}</a></aside><div class="full-curation">${list.length?cardGrid(list):`<div class="empty-state">${icon('bookmark')}<h2>아직 저장한 추천이 없어요.</h2><p>웨딩 추천에서 ‘저장’을 누르면 여기에 모여요.</p><a href="#curation" class="solid-button">웨딩 추천 보기 ${icon('arrow')}</a></div>`}</div></section>`}
function render(){const top=window.scrollY,left=window.scrollX;const previousPage=app.dataset.page;page=location.hash.slice(1).split('?')[0]||'home';if(!names[page])page='home';app.innerHTML=Journal.nav(page)+({home,checklist:()=>Planner.render(),roadmap:()=>Planner.render(),budget,halls:()=>VenueExplorer.render(),survey:()=>VenueSurvey.render(),curation}[page]||Journal.render)();document.querySelector('#breadcrumb').textContent=names[page];document.querySelector('#page-number').textContent=pageNums[page];document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a.dataset.page===Journal.groupOf(page));if(a.dataset.page===Journal.groupOf(page))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});hydrateIcons();VenueExplorer.afterRender();Journal.afterRender();app.dataset.page=page;app.classList.remove('page-enter');if(previousPage!==page){void app.offsetWidth;app.classList.add('page-enter');observeReveals()}else window.scrollTo({left,top,behavior:'instant'})}
let toastTimeout;function toast(message){let el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>el.classList.remove('visible'),2600)}
const dialog=document.querySelector('#dialog');let dialogTrigger;function openDialog(html){dialogTrigger=document.activeElement;document.querySelector('#dialog-content').innerHTML=html;const title=dialog.querySelector('h2,h3');if(title)title.id='dialog-title';dialog.showModal()}
dialog.addEventListener('close',()=>{if(dialogTrigger?.isConnected)dialogTrigger.focus({preventScroll:true})});document.querySelector('.dialog-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){const id=save.dataset.save;if(saved.has(id)){saved.delete(id);toast('저장 목록에서 삭제했어요.')}else{saved.add(id);toast('저장했어요. ‘저장한 추천’에서 다시 볼 수 있어요.')}render();document.querySelector(`[data-save="${id}"]`)?.focus({preventScroll:true});return}const detail=e.target.closest('[data-detail]');if(detail){const c=cards.find(c=>c.id===detail.dataset.detail);openDialog(`<span class="section-eyebrow">${c.categoryKo} · 준비 가이드</span><h3>${c.title}</h3><img src="${c.image}" alt="${c.title}"><p>${c.description}</p><h4>준비할 때 함께 확인해요</h4><ul>${c.tips.map(t=>`<li>${t}</li>`).join('')}</ul><p class="note-label">업체 예약 페이지가 아닌 준비 가이드 예시입니다.</p>`);return}const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;render();document.querySelector(`[data-filter="${filter}"]`).focus({preventScroll:true})}const c=e.target.closest('[data-category]');if(c){curationFilter=c.dataset.category;render();document.querySelector(`[data-category="${curationFilter}"]`).focus({preventScroll:true})}});
document.querySelector('#notification').onclick=()=>openDialog(`<span class="section-eyebrow">준비 일정</span><h2>다가오는 할 일</h2><div>${Planner.upcoming()}</div><div class="j-dialog-actions"><button class="solid-button" onclick="dialog.close();location.hash='checklist'">나의 할 일 보기</button></div>`);
document.querySelector('.mobile-menu').onclick=e=>{const open=document.querySelector('#sidebar').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)};
document.addEventListener('click',e=>{if(!e.target.closest('.sidebar,.mobile-menu')){document.querySelector('#sidebar').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false')}});
let revealObserver;
function observeReveals(){
 revealObserver?.disconnect();
 if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 revealObserver=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('revealed');revealObserver.unobserve(entry.target)}},{threshold:.06});
 document.querySelectorAll('.reveal').forEach(el=>{el.classList.add('will-reveal');revealObserver.observe(el)});
}
window.addEventListener('hashchange' ,()=>{render();document.querySelector('#sidebar').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false');window.scrollTo(0,0)});document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('#sidebar').classList.remove('open');document.querySelector('.mobile-menu').setAttribute('aria-expanded','false')}});render();

// Optional agent interface for the same persistent planner state as the UI.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
 const definitions=[
 {name:'read_wedding_checklist',description:'Read wedding planning tasks and their locally saved progress.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({tasks:Planner.all()})},
 {name:'set_wedding_task_completion',description:'Set completion of wedding tasks and save progress in this browser.',inputSchema:{type:'object',properties:{taskIds:{type:'array',items:{type:'string'},minItems:1},completed:{type:'boolean'}},required:['taskIds','completed'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||!Array.isArray(input.taskIds)||!input.taskIds.length||typeof input.completed!=='boolean'||input.taskIds.some(id=>typeof id!=='string'||!Planner.all().some(t=>t.id===id)))throw new Error('Valid task IDs and a boolean completed value are required.');Planner.setCompletion(input.taskIds,input.completed);return {updated:input.taskIds,completed:input.completed};}}
 ];
 definitions.forEach(tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}});
}
